import hashlib

class Solver:
    """Fast SHA-256 hashing using Python's built-in hashlib (OpenSSL C implementation)."""

    @staticmethod
    def solve(problem, **kwargs):  # type: ignore[override]
        plaintext = problem["plaintext"]
        # hashlib's sha256 is significantly faster than the cryptography high-level API
        digest = hashlib.sha256(plaintext).digest()
        return {"digest": digest}
